import { PortfolioItem } from "@/types";

/*
 * Real Eterna celebrations. Photos are generated by scripts/optimize_assets.py
 * from the originals in assets-src/ (see public/images/events/manifest.json).
 * Location and date are left blank until confirmed — the project page hides
 * empty fields. Lists skip near-identical frames from the same burst so the
 * galleries don't feel repetitive; lib/media.ts decides where else each photo
 * may appear on the site.
 */
